diff --git a/specs/2/SPEC.md b/specs/2/SPEC.md
new file mode 100644
index 0000000..1e7b96a
--- /dev/null
+++ b/specs/2/SPEC.md
@@ -0,0 +1,33 @@
+# Spec: issue 2, splitting a damage charge loses a cent
+
+## Outcome
+
+When a damage charge does not divide evenly between borrowers, every penny is still billed to someone.
+Splitting £33.33 (3333 cents) two ways gives £16.67 and £16.66, which add up to £33.33.
+
+## Requirements
+
+- The system shall return shares that add up to exactly the charge in cents.
+- When the charge does not divide evenly, the system shall give the leftover cents to the first borrowers, one cent each, so 3333 split 2 ways is [1667, 1666].
+- The system shall keep every share within one cent of every other share.
+- When the charge divides evenly, the system shall give every borrower the same share.
+- If the charge is not a whole number of cents or is negative, then the system shall refuse it with an error.
+- If the number of ways is not a whole number or is less than 1, then the system shall refuse it with an error.
+
+## Must not change
+
+- Amounts stay integer cents; no floats.
+- `splitCharge(totalCents, ways)` keeps its name, arguments and return type (an array of `ways` numbers).
+- Existing tests in `tests/fees/split.test.ts` keep passing.
+- Nothing under `src/auth/` changes.
+
+## Out of scope
+
+- Splitting in proportion to anything other than equal shares.
+- Late fees (`src/fees/late.ts`) and the desk command's output format.
+- Any change to the tests that already exist.
+
+## Done when
+
+- The new tests in `tests/fees/split.test.ts` pass.
+- `bun run gate` exits 0.
diff --git a/src/fees/split.ts b/src/fees/split.ts
index 808a476..b7b52c5 100644
--- a/src/fees/split.ts
+++ b/src/fees/split.ts
@@ -4,5 +4,6 @@ export function splitCharge(totalCents: number, ways: number): number[] {
     throw new Error("totalCents must be a whole number of cents");
   if (!Number.isInteger(ways) || ways < 1) throw new Error("ways must be at least 1");
   const share = Math.floor(totalCents / ways);
-  return Array.from({ length: ways }, () => share);
+  const leftover = totalCents - share * ways;
+  return Array.from({ length: ways }, (_, index) => (index < leftover ? share + 1 : share));
 }
diff --git a/tests/fees/split.test.ts b/tests/fees/split.test.ts
index 936c6bf..c0792b5 100644
--- a/tests/fees/split.test.ts
+++ b/tests/fees/split.test.ts
@@ -12,3 +12,37 @@ test("one borrower pays the whole charge", () => {
 test("a negative charge is refused", () => {
   expect(() => splitCharge(-1, 2)).toThrow();
 });
+
+function total(shares: number[]): number {
+  return shares.reduce((sum, share) => sum + share, 0);
+}
+
+test("the shares add up to exactly the charge", () => {
+  expect(total(splitCharge(3333, 2))).toBe(3333);
+  expect(total(splitCharge(1000, 3))).toBe(1000);
+  expect(total(splitCharge(1, 4))).toBe(1);
+});
+
+test("leftover cents go to the first borrowers, one cent each", () => {
+  expect(splitCharge(3333, 2)).toEqual([1667, 1666]);
+  expect(splitCharge(1000, 3)).toEqual([334, 333, 333]);
+  expect(splitCharge(2, 3)).toEqual([1, 1, 0]);
+});
+
+test("no share is more than one cent from another", () => {
+  const shares = splitCharge(9999, 7);
+  expect(Math.max(...shares) - Math.min(...shares)).toBeLessThanOrEqual(1);
+});
+
+test("an even charge gives every borrower the same share", () => {
+  expect(splitCharge(3000, 3)).toEqual([1000, 1000, 1000]);
+});
+
+test("a fractional charge is refused", () => {
+  expect(() => splitCharge(33.5, 2)).toThrow();
+});
+
+test("zero or fractional ways is refused", () => {
+  expect(() => splitCharge(100, 0)).toThrow();
+  expect(() => splitCharge(100, 1.5)).toThrow();
+});

